CREATE FUNCTION public.revenue_branch(p text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN lower(coalesce(p,'')) LIKE '%bonn%' THEN 'bonn' WHEN lower(coalesce(p,'')) LIKE '%krefeld%' OR lower(coalesce(p,'')) LIKE '%mülheim%' OR lower(coalesce(p,'')) LIKE '%muelheim%' THEN 'krefeld' ELSE NULL END $$;
CREATE FUNCTION public.revenue_number(p text) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN IF p IS NULL OR p !~ '^-?[0-9]+([.][0-9]+)?$' THEN RETURN NULL; END IF; RETURN p::numeric; END $$;
CREATE FUNCTION public.revenue_time(p text) RETURNS timestamptz LANGUAGE plpgsql STABLE SET search_path=public AS $$ BEGIN RETURN p::timestamptz; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $$;
CREATE FUNCTION public.revenue_scope() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE loc text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Bitte anmelden' USING ERRCODE='42501'; END IF; IF public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid()) THEN RETURN jsonb_build_object('admin',true,'location',NULL); END IF; IF public.has_role(auth.uid(),'niederlassungsleiter') THEN SELECT public.revenue_branch(s.location) INTO loc FROM public.staff_profiles s WHERE s.user_id=auth.uid() AND s.is_active=true; END IF; IF loc IS NULL THEN RAISE EXCEPTION 'Keine Berechtigung zur Umsatzauswertung oder kein aktiver Standort' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('admin',false,'location',loc); END $$;
REVOKE ALL ON FUNCTION public.revenue_scope() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.revenue_scope() TO authenticated,service_role;
CREATE TABLE public.revenue_events(id text PRIMARY KEY,source_table text NOT NULL,source_id uuid NOT NULL,stage text NOT NULL CHECK(stage IN('offered','accepted','invoiced')),business text NOT NULL CHECK(business IN('rental','sales')),event_date date,occurred_at timestamptz,location text,document_number text,order_code text,customer_name text,segment text NOT NULL,event_kind text NOT NULL,net_amount numeric(16,2),lines jsonb NOT NULL DEFAULT '[]',warning text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.revenue_events TO authenticated; GRANT ALL ON public.revenue_events TO service_role;
ALTER TABLE public.revenue_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY revenue_events_read ON public.revenue_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'niederlassungsleiter') AND location IN(SELECT public.revenue_branch(s.location) FROM public.staff_profiles s WHERE s.user_id=auth.uid() AND s.is_active=true)));
CREATE INDEX revenue_events_period ON public.revenue_events(location,event_date,stage,business);
CREATE INDEX revenue_events_source ON public.revenue_events(source_table,source_id,stage);
COMMENT ON TABLE public.revenue_events IS 'Documentary analytics. Missing evidence remains NULL; stages are independent.';
CREATE FUNCTION public.revenue_lines(items jsonb,payload jsonb,total numeric,business text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb:='[]'; i jsonb; a jsonb; vname text; cat text; amount numeric; accounted numeric:=0; BEGIN
IF total IS NULL THEN RETURN result; END IF;
FOR i IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(items)='array' THEN items ELSE '[]'::jsonb END) LOOP
vname:=coalesce(nullif(i->>'product_name',''),'Ohne Bezeichnung'); IF lower(vname) ~ '^kaution' THEN CONTINUE; END IF;
amount:=coalesce(public.revenue_number(i->>'total_price'),round(public.revenue_number(i->>'unit_price')*public.revenue_number(i->>'quantity')*(1-coalesce(public.revenue_number(i->>'discount_percent'),0)/100),2)); IF amount IS NULL THEN CONTINUE; END IF;
IF total<0 THEN amount:=-abs(amount); END IF; cat:=NULL;
IF lower(vname) ~ '^(anlieferung|lieferung|abholung|transport|aufbau|abbau|fracht)' THEN cat:='Lieferung & Service'; ELSIF lower(vname) ~ '(versicherung|haftungsreduzierung|reinigung|zusatzoption|selbstbeteiligung)' THEN cat:='Versicherung & Zusatzoptionen'; ELSIF business='rental' THEN SELECT m.category INTO cat FROM public.b2b_managed_products m WHERE m.slug=i->>'product_slug' OR lower(vname)=lower(m.name) ORDER BY (m.slug=i->>'product_slug') DESC NULLS LAST LIMIT 1; ELSE SELECT x.category INTO cat FROM (SELECT m.slug,m.name,m.category FROM public.new_machines m UNION ALL SELECT m.slug,concat_ws(' ',m.manufacturer,m.model),m.category FROM public.used_machines m) x WHERE x.slug=i->>'product_slug' OR lower(x.name)=lower(vname) LIMIT 1; END IF;
result:=result||jsonb_build_array(jsonb_build_object('name',vname,'category',coalesce(cat,'Ohne Kategorie'),'net',amount)); accounted:=accounted+amount;
FOR a IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(i->'addons')='array' THEN i->'addons' ELSE '[]'::jsonb END) WHERE coalesce(value->>'optional','false')<>'true' LOOP
amount:=public.revenue_number(a->>'amount'); IF amount IS NULL THEN CONTINUE; END IF; IF total<0 THEN amount:=-abs(amount); END IF;
result:=result||jsonb_build_array(jsonb_build_object('name',coalesce(a->>'label','Zusatzoption'),'category','Versicherung & Zusatzoptionen','net',amount)); accounted:=accounted+amount;
END LOOP; END LOOP;
amount:=coalesce(public.revenue_number(payload->>'delivery_cost_delivery'),0)+coalesce(public.revenue_number(payload->>'delivery_cost_return'),0)+coalesce(public.revenue_number(payload->>'setup_cost'),0)+coalesce(public.revenue_number(payload->>'dismantle_cost'),0)+coalesce(public.revenue_number(payload->>'return_location_cost'),0)+coalesce(public.revenue_number(payload->>'delivery_cost'),0);
IF total<0 THEN amount:=-abs(amount); END IF;
IF amount<>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result) x WHERE x->>'category'='Lieferung & Service') AND abs(total-accounted)>=abs(amount)-0.01 THEN result:=result||jsonb_build_array(jsonb_build_object('name','Lieferung & Service','category','Lieferung & Service','net',amount)); accounted:=accounted+amount; END IF;
IF round(total-accounted,2)<>0 THEN result:=result||jsonb_build_array(jsonb_build_object('name','Nicht aufgeschlüsselt','category','Nicht aufgeschlüsselt','net',round(total-accounted,2))); END IF;
RETURN result; END $$;
CREATE FUNCTION public.revenue_record(r jsonb,t text,s text,k text,stamp timestamptz,net numeric,payload jsonb,custom_lines jsonb DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b text:=CASE WHEN t='sales_inquiries' OR r->>'inquiry_type'='sales' THEN 'sales' ELSE 'rental' END; branch text; BEGIN
branch:=public.revenue_branch(coalesce(nullif(r->>'issuing_location',''),r->>'location'));
INSERT INTO public.revenue_events(id,source_table,source_id,stage,business,event_date,occurred_at,location,document_number,order_code,customer_name,segment,event_kind,net_amount,lines,warning)
VALUES(t||':'||(r->>'id')||':'||s||':'||k,t,(r->>'id')::uuid,s,b,(stamp AT TIME ZONE 'Europe/Berlin')::date,stamp,branch,coalesce(r->>'invoice_number',payload->>'offer_number',r->>'offer_number'),r->>'order_code',coalesce(nullif(r->>'company_name',''),r->>'customer_company',r->>'customer_name',nullif(concat_ws(' ',r->>'first_name',r->>'last_name'),'')),CASE WHEN t LIKE 'b2b_%' OR r->>'b2b_profile_id' IS NOT NULL OR r->>'source'='b2b_portal' THEN 'portal' WHEN r->>'customer_kind' IN('business','b2b') THEN 'business' ELSE 'private' END,k,net,coalesce(custom_lines,public.revenue_lines(payload->'items',payload,net,b)),nullif(concat_ws(' · ',CASE WHEN net IS NULL THEN 'Nettobetrag nicht eindeutig belegt' END,CASE WHEN stamp IS NULL THEN 'Datum nicht belegt' END,CASE WHEN branch IS NULL THEN 'Standort nicht belegt' END),'')) ON CONFLICT(id) DO NOTHING;
END $$;
REVOKE ALL ON FUNCTION public.revenue_lines(jsonb,jsonb,numeric,text),public.revenue_record(jsonb,text,text,text,timestamptz,numeric,jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.revenue_lines(jsonb,jsonb,numeric,text),public.revenue_record(jsonb,text,text,text,timestamptz,numeric,jsonb,jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.revenue_number(text),public.revenue_time(text),public.revenue_branch(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.revenue_number(text),public.revenue_time(text),public.revenue_branch(text) TO authenticated,service_role;